function reportPeriodLabel(){return reportMode==='range'?`${reportFrom} s.d. ${reportTo}`:month}
function eventInSelectedReport(e){if(reportMode==='range')return !!reportFrom&&!!reportTo&&e.date>=reportFrom&&e.date<=reportTo;return e.date.startsWith(month)}
function reportChannelMatch(e){const ch=reportChannel(e);return channel==='all'||channel===ch||(channel==='online'&&(ch==='shopee'||ch==='online'))}
function selectedSharedEvents(){return activeEvents().filter(e=>eventInSelectedReport(e)&&reportChannel(e)==='shared').filter(e=>{const o=calc.outcomes[e.id]||{};return !!((o.revenue||0)||(o.cogs||0)||(o.cost||0)||(o.profit||0))})}
function sharedEventTitle(e){const d=e.data||{};if(e.type==='adjust')return d.productId?'Stok opname '+(calc.products[d.productId]?.name||'telur'):'Stok opname tray';if(e.type==='expense')return d.name||'Biaya usaha';if(e.type==='return')return 'Retur '+(calc.products[d.productId]?.name||'telur');if(e.type==='settlement')return 'Penyelesaian retur / bon';if(e.type==='initial')return 'Stok / saldo awal';return kindNames[e.type]||e.type}
function sharedEventMeta(e){const d=e.data||{},o=calc.outcomes[e.id]||{};if(e.type==='adjust'&&d.productId)return `Stok fisik ${fmt(d.actual||0)} gram · Dampak HPP ${rupiah(o.cogs||0)}`;if(e.type==='adjust')return `Tray layak ${fmt(d.trayAvailable||0)} pcs · rusak ${fmt(d.trayBroken||0)} pcs`;if(e.type==='expense')return `${d.name||'Biaya'} · ${rupiah(d.amount||o.cost||0)}`;if(e.type==='return')return `${fmt(d.weight||0)} gram · ${d.direction==='supplier'?'Ke supplier':d.direction==='customer'?'Dari customer':'Busuk di gudang'}`;return `${kindNames[e.type]||e.type} · HPP ${rupiah(o.cogs||0)} · Biaya ${rupiah(o.cost||0)}`}
function sharedCostDetail(){const rows=selectedSharedEvents(),total=rows.reduce((n,e)=>n+(calc.outcomes[e.id]?.profit||0),0);modal('Detail Biaya bersama / penyesuaian',`<p class="hint">Daftar transaksi pada periode laporan yang masuk kategori bersama/belum dialokasikan. Klik baris untuk melihat detail transaksi asal.</p><div class="detail-grid"><div class="detail-item"><span>Jumlah transaksi</span><b>${fmt(rows.length)}</b></div><div class="detail-item"><span>Total dampak laba</span><b>${rupiah(total)}</b></div></div><div class="shared-detail-list">${rows.map(e=>{const o=calc.outcomes[e.id]||{};return `<button type="button" class="report-list-button" data-shared-event="${esc(e.id)}"><span><b>${esc(sharedEventTitle(e))}</b><small>${esc(e.date)} · ${esc(sharedEventMeta(e))}</small></span><strong>${rupiah(o.profit||0)}</strong></button>`}).join('')||'<p class="empty">Tidak ada biaya atau penyesuaian bersama pada periode ini.</p>'}</div>`);document.querySelectorAll('[data-shared-event]').forEach(b=>b.onclick=()=>transactionDetail(b.dataset.sharedEvent))}
function salePagination(total){const pages=Math.max(1,Math.ceil(total/salePageSize));salePage=Math.min(Math.max(1,salePage),pages);return `<div class="pagination"><div class="page-size"><label>Tampilkan <select id="salePageSize">${[10,20,50].map(n=>`<option value="${n}" ${salePageSize===n?'selected':''}>${n}</option>`).join('')}</select> / halaman</label></div><div class="page-nav"><button class="outline" data-sale-page="first" ${salePage===1?'disabled':''}>«</button><button class="outline" data-sale-page="prev" ${salePage===1?'disabled':''}>‹</button><span>Halaman <b>${salePage}</b> / ${pages} · ${total} data</span><button class="outline" data-sale-page="next" ${salePage===pages?'disabled':''}>›</button><button class="outline" data-sale-page="last" ${salePage===pages?'disabled':''}>»</button></div></div>`}
