 if(view==='dashboard')html=`<div class="hero"><div><span>CANGKANG MAS · ${esc(month)}</span><h2>${rupiah(reports.all.profit)}</h2><p>Laba seluruh saluran bulan ini</p></div><img class="hero-logo" src="assets/logo.png"></div><div class="grid four">${card('Stok telur',fmt(stock)+' gram')}${card('Tray fisik layak',fmt(calc.tray.available)+' pcs')}${card('Laba offline',rupiah(reports.offline.profit))}${card('Laba online',rupiah(reports.online.profit))}</div><div class="card"><h2>Transaksi cepat</h2><div class="actions">${[['purchase','Kulak telur'],['sale','Jual telur'],['tray','Tray'],['return','Retur']].map(([k,t])=>`<button class="action" data-new="${k}">${t}</button>`).join('')}</div></div><div class="grid">${card('Bon customer',rupiah(receivable))}${card('Tray di customer',fmt(trayDue)+' pcs')}</div><div class="card"><h2>Riwayat terbaru</h2>${historyRows(activeEvents().filter(e=>!['product','contact','productUpdate','contactUpdate'].includes(e.type)).slice(0,6))}</div>`;
 if(view==='sale'){const sales=activeEvents().filter(e=>e.type==='sale'),pages=Math.max(1,Math.ceil(sales.length/salePageSize));salePage=Math.min(Math.max(1,salePage),pages);const start=(salePage-1)*salePageSize;html=`<h1 class="page-title">Jual telur</h1><p class="subtitle">Bisa beberapa jenis telur dalam satu transaksi, harga default otomatis, FIFO per item.</p><div class="card"><button class="primary" data-new="sale">+ Input penjualan</button> <button class="outline" data-new="contact">+ Customer</button></div><div class="card"><h2>Riwayat penjualan</h2>${historyRows(sales.slice(start,start+salePageSize),false,{showSeq:true,startIndex:start})}${salePagination(sales.length)}</div>`;}
