function customerDetail(id){const c=calc.contacts[id];if(!c)return;modal(c.name,`<h3>Bon ${rupiah(c.debt)} · Tray ${fmt(c.trayDue)} pcs</h3><button class="primary" id="payCustomer">Bayar bon / retur</button><h3>Nota penjualan</h3>${historyRows(activeEvents().filter(e=>e.type==='sale'&&e.data?.partyId===id))}`);$('payCustomer').onclick=()=>{sectionAction('add','settlement');$('editForm').elements.namedItem('partyId').value=id;$('editForm').elements.namedItem('partyId').dispatchEvent(new Event('change'))};document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>transactionDetail(b.dataset.detail));document.querySelectorAll('[data-receipt]').forEach(b=>b.onclick=()=>receipt(b.dataset.receipt))}
function manage(restore=false){manageEditing=false;formDirty=false;modal('Kelola Data · Edit & Hapus',`<p class="hint">Khusus memperbaiki input salah. Setelah Simpan atau Close dari form Edit, Anda kembali ke daftar ini.</p><div class="form-grid">${choose('Kategori','manageType',[['all','Semua'],...Object.entries(kindNames).map(([k,v])=>[k,v])],restore?manageState.type:'all')}${field('Cari nama / tanggal / nomor','manageSearch',restore?manageState.term:'',{type:'text'})}</div><div id="manageResults"></div>`);const typeEl=$('modalBody').querySelector('[name=manageType]'),searchEl=$('modalBody').querySelector('[name=manageSearch]');const draw=()=>{manageState.type=typeEl.value;manageState.term=searchEl.value;const type=manageState.type,term=manageState.term.toLowerCase(),rows=activeEvents().filter(e=>(type==='all'||e.type===type)&&[e.id,e.date,e.data?.name,e.data?.note,e.data?.productId,JSON.stringify(e.data?.items||[]),kindNames[e.type],calc.contacts[e.data?.partyId]?.name].some(s=>String(s||'').toLowerCase().includes(term)));$('manageResults').innerHTML=historyRows(rows,true);document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{manageState.scroll=$('modal').querySelector('.modal-card')?.scrollTop||0;manageEditing=true;formDirty=false;sectionAction('edit',events.find(e=>e.id===b.dataset.edit).type,b.dataset.edit)});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteForm(b.dataset.delete))};typeEl.onchange=draw;searchEl.oninput=draw;draw();if(restore)setTimeout(()=>{const c=$('modal').querySelector('.modal-card');if(c)c.scrollTop=manageState.scroll||0},0)}
async function saveProductPrices(form){if(busy)return;try{const changes=products().map(p=>({p,value:integer(form.elements.namedItem('price_'+p.id).value||'0','Harga '+p.name)})).filter(x=>x.value!==(x.p.salePrice||0));if(!changes.length){show('Tidak ada perubahan harga.');close();return}busy=true;const snap=await getDocsFromServer(collection(db,'users',uid,'events')),current=normalized(snap),maxSeq=Math.max(0,...current.map(e=>e.seq||0));await runTransaction(db,async tx=>{const guard=await tx.get(revisionRef()),revision=guard.exists()?guard.data().value||0:0;required(revision===current.length,'Data berubah di perangkat lain. Ulangi simpan harga.');changes.forEach((x,i)=>{const id=newId();tx.set(eventRef(id),{id,type:'productUpdate',date:today(),seq:maxSeq+i+1,voided:false,label:kindNames.productUpdate,data:{target:x.p.id,name:x.p.name,active:x.p.active!==false,salePrice:x.value}})});tx.set(revisionRef(),{value:revision+changes.length,updatedAt:new Date().toISOString()})});close();show('Harga jual default tersimpan.')}catch(e){show(e.message,true)}finally{busy=false}}
function priceSettings(){modal('Pengaturan Harga Produk',`<form id="priceSettingsForm"><div class="form-grid">${products().map(p=>field('Harga '+p.name+' / kg (Rp)','price_'+p.id,fmt(p.salePrice||0),{required:true,placeholder:'0'})).join('')}</div><p class="hint">Harga ini otomatis dipakai transaksi Offline/Online. Harga khusus tetap dapat diubah per item saat checkbox Harga khusus aktif.</p><div class="form-actions"><button class="primary" type="submit">Simpan Harga</button></div></form>`);const f=$('priceSettingsForm');f.addEventListener('focusin',e=>{const el=e.target;if(el instanceof HTMLInputElement&&el.inputMode==='numeric'&&integer(el.value||'0')===0)el.value=''});f.onsubmit=e=>{e.preventDefault();saveProductPrices(f)}}
function debtDetail(id){const i=calc.invoices[id],c=i&&calc.contacts[i.partyId];if(!i||i.debt<=0)return;const payments=activeEvents().filter(e=>e.type==='settlement'&&e.data?.mode==='debt'&&e.data?.invoiceId===id);modal('Bon Aktif · '+(c?.name||'Customer'),`<div class="detail-grid"><div class="detail-item"><span>Tanggal</span><b>${esc(i.date)}</b></div><div class="detail-item"><span>Total tagihan</span><b>${rupiah(i.revenue||0)}</b></div><div class="detail-item"><span>Sudah dibayar</span><b>${rupiah(i.paid||0)}</b></div><div class="detail-item"><span>Sisa bon</span><b>${rupiah(i.debt||0)}</b></div></div><h3>Riwayat cicilan</h3>${payments.map(e=>`<div class="row debt-payment-row"><span>${esc(e.date)}</span><b>${rupiah(e.data?.amount||0)}</b></div>`).join('')||'<p class="empty">Belum ada cicilan setelah transaksi awal.</p>'}<div class="form-actions"><button class="secondary" id="debtInstallment">Bayar cicilan</button><button class="primary" id="debtFull">Lunasi</button></div>`);const openPay=full=>{sectionAction('add','settlement');const f=$('editForm');f.elements.namedItem('partyId').value=i.partyId;f.elements.namedItem('partyId').dispatchEvent(new Event('change'));f.elements.namedItem('invoiceId').value=id;f.elements.namedItem('mode').value='debt';f.elements.namedItem('amount').value=fmt(full?i.debt:0)};$('debtInstallment').onclick=()=>openPay(false);$('debtFull').onclick=()=>openPay(true)}
function fileDownload(name,body,type){const u=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),60000)}
async function backup(){try{const snap=await getDocsFromServer(collection(db,'users',uid,'audit'));const audits=normalized(snap);fileDownload('cangkang-mas-backup-'+today()+'.json',JSON.stringify({exportedAt:new Date().toISOString(),version:2,events,audits},null,2),'application/json');show('Backup data dan riwayat koreksi berhasil dibuat. Simpan di tempat aman.')}catch(e){show('Gagal membuat backup lengkap: '+e.message,true)}}
async function restore(file){if(busy)return;try{required(file.size<3_000_000,'File backup terlalu besar untuk pemulihan satu transaksi.');const data=JSON.parse(await file.text());required(data.version===2&&Array.isArray(data.events)&&Array.isArray(data.audits),'Format backup Cangkang Mas V2 tidak sesuai.');required(data.events.length+data.audits.length<=400,'Backup terlalu banyak transaksi untuk pemulihan atomik browser. Jangan impor sebagian data.');const ids=new Set();for(const e of data.events){required(typeof e.id==='string'&&e.id.length>=8&&!e.id.includes('/')&&typeof e.type==='string'&&!ids.has(e.id),'ID transaksi backup tidak valid atau ganda.');ids.add(e.id)}for(const e of data.audits){required(typeof e.id==='string'&&e.id.length>=8&&!e.id.includes('/'),'ID audit backup tidak valid.')}replay(data.events);const existing=await getDocsFromServer(collection(db,'users',uid,'events'));required(existing.empty||existing.docs.length===0,'Database tidak kosong. Pemulihan ditolak agar tidak menggandakan transaksi.');required(confirm('Pulihkan '+data.events.length+' transaksi ke database kosong? Semua data dan riwayat koreksi pada file akan dibuat kembali.'),'Pemulihan dibatalkan.');busy=true;await runTransaction(db,async tx=>{const guard=await tx.get(revisionRef());required(!guard.exists()||(guard.data().value||0)===0,'Database pernah berisi transaksi. Jangan pulihkan tanpa memeriksa data.');for(const e of data.events)tx.set(eventRef(e.id),e);for(const a of data.audits)tx.set(doc(db,'users',uid,'audit',a.id),a);tx.set(revisionRef(),{value:data.events.length,updatedAt:new Date().toISOString()})});show('Pemulihan selesai. Tunggu sinkronisasi Dashboard.')}catch(e){show('Pemulihan tidak dilakukan: '+e.message,true);console.error(e)}finally{busy=false}}
function csv(){const selected=activeEvents().filter(e=>eventInSelectedReport(e)&&reportChannelMatch(e)),rows=[['Tanggal','Kategori','Saluran','Pihak','Jenis telur','Berat','Pendapatan','HPP','Biaya','Laba'],...selected.map(e=>{const o=calc.outcomes[e.id]||{},d=e.data||{};const saleItems=e.type==='sale'?saleItemsOf(d):[],productName=saleItems.length?saleItems.map(x=>calc.products[x.productId]?.name||'').filter(Boolean).join(' + '):(calc.products[d.productId]?.name||''),weight=saleItems.length?saleItems.reduce((n,x)=>n+(Number(x.weight)||0),0):(d.weight||0);return [e.date,kindNames[e.type],reportChannel(e),calc.contacts[d.partyId]?.name||'',productName,weight,o.revenue||0,o.cogs||0,o.cost||0,o.profit||0]})],label=reportMode==='range'?`${reportFrom}-sd-${reportTo}`:month;fileDownload('cangkang-mas-'+label+'.csv','\ufeff'+rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\r\n'),'text/csv;charset=utf-8')}
$('nav').onclick=e=>{const b=e.target.closest('[data-page]');if(!b)return;view=b.dataset.page;render();window.scrollTo(0,0)};
async function boot(){const firebase=initializeApp(firebaseConfig);auth=getAuth(firebase);db=getFirestore(firebase);await setPersistence(auth,browserLocalPersistence);await auth.authStateReady();$('loading').hidden=true;onAuthStateChanged(auth,user=>{if(user&&!user.isAnonymous){if(uid===user.uid)return;uid=user.uid;unsub?.();loaded=false;events=[];$('login').hidden=true;$('app').hidden=false;$('sync').textContent='● Memuat data';unsub=onSnapshot(collection(db,'users',uid,'events'),snapshot=>{try{const incoming=normalized(snapshot);const next=replay(incoming);events=incoming;calc=next;loaded=true;$('sync').textContent=snapshot.metadata.fromCache?'● Cache lokal':'● Data Firebase';render()}catch(err){$('sync').textContent='● Periksa data';show('Data belum konsisten: '+err.message,true);console.error(err)}},err=>{$('sync').textContent='● Koneksi bermasalah';show('Gagal membaca Firebase: '+err.message,true)})}else{uid='';unsub?.();loaded=false;$('app').hidden=true;$('login').hidden=false}});$('loginForm').onsubmit=async e=>{e.preventDefault();$('loginBtn').disabled=true;$('loginMessage').textContent='Memeriksa akun...';try{await signInWithEmailAndPassword(auth,$('loginEmail').value.trim(),$('loginPassword').value);$('loginPassword').value=''}catch(err){$('loginMessage').textContent=err.code==='auth/invalid-credential'?'Email atau password salah.':err.message}finally{$('loginBtn').disabled=false}};$('logoutBtn').onclick=async()=>{if(confirm('Keluar dari browser ini?'))await signOut(auth)}}
boot().catch(e=>{$('loading').hidden=true;$('login').hidden=false;$('loginMessage').textContent='Gagal memulai: '+e.message;console.error(e)});


// Ikon aplikasi SVG lokal; invoice tidak memakai ikon menu maupun gambar produk.
const iconPaths={
 home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',
 sale:'<path d="M3 4h2l2.2 10h11l2-7H6"/><circle cx="9" cy="20" r="1"/><circle cx="18" cy="20" r="1"/>',
 stock:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18M9 9v12"/>',
 report:'<path d="M4 20V10m5 10V4m5 16v-7m5 7V8"/>',
 more:'<path d="M4 7h16M4 12h16M4 17h16"/>',
 purchase:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',
 tray:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 12h18M9 5v14m6-14v14"/>',
 return:'<path d="M9 14 4 9l5-5M4 9h10a6 6 0 0 1 0 12h-2"/>',
 debt:'<rect x="2" y="6" width="20" height="15" rx="2"/><path d="M2 10h20M16 16h3"/>',
 customer:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',
 edit:'<path d="m4 20 4-.8L20 7a2 2 0 0 0-3-3L5 16z"/>',
 delete:'<path d="M4 7h16M10 4h4M6 7l1 14h10l1-14M10 11v6m4-6v6"/>',
 save:'<path d="M5 3h13l3 3v15H3V3h2zm1 0v7h11V3M7 21v-8h10v8"/>',
 print:'<path d="M6 9V3h12v6M6 18H4V9h16v9h-2M6 15h12v6H6zM17 12h1"/>',
 whatsapp:'<path d="M20 11.5a8.5 8.5 0 0 1-12.3 7.6L3 21l1.9-4.6A8.5 8.5 0 1 1 20 11.5z"/><path d="M9 9c1 3 3 5 6 6l1.5-1.5"/>',
 plus:'<path d="M12 4v16M4 12h16"/>',
 download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',
 search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',
 default:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>'
};
function smallIcon(name){return `<svg class="cm-svg" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${iconPaths[name]||iconPaths.default}</svg>`;}
function iconFor(b){const page=b.dataset.page;if(page)return {dashboard:'home',sale:'sale',stock:'stock',reports:'report',more:'more'}[page]||'default';
 const type=b.dataset.new;if(type)return {purchase:'purchase',sale:'sale',tray:'tray',return:'return',settlement:'debt',expense:'debt',contact:'customer',product:'stock',adjust:'stock',initial:'plus'}[type]||'plus';
 const label=(b.textContent||'').trim().toLowerCase();
 if(b.dataset.delete||/hapus|batalkan input/.test(label))return 'delete';
 if(b.dataset.edit||/edit|koreksi|kelola data/.test(label))return 'edit';
 if(/whatsapp|bagikan/.test(label))return 'whatsapp';
 if(/cetak/.test(label))return 'print';
 if(/simpan png|ekspor|backup|unduh/.test(label))return 'download';
 if(/simpan|konfirmasi|pulihkan/.test(label))return 'save';
 if(/nota|invoice/.test(label))return 'print';
 if(/bon|bayar|cicilan/.test(label))return 'debt';
 if(/customer|supplier/.test(label))return 'customer';
 if(/kulak/.test(label))return 'purchase';
 if(/jual|penjualan/.test(label))return 'sale';
 if(/tray/.test(label))return 'tray';
 if(/retur/.test(label))return 'return';
 if(/stok/.test(label))return 'stock';
 if(/laporan/.test(label))return 'report';
 if(/tambah|buat/.test(label))return 'plus';
 return null;
}
function decorateIcons(){document.querySelectorAll('#app button,#modal button').forEach(b=>{
 if(b.dataset.cmIconized)return;const kind=iconFor(b);if(!kind)return;
 b.dataset.cmIconized='1';if(b.dataset.page){const old=b.querySelector('span');if(old){old.innerHTML=smallIcon(kind);old.classList.add('cm-nav-icon');}}else{
  const holder=document.createElement('span');holder.className='cm-button-icon';holder.innerHTML=smallIcon(kind);b.prepend(holder);b.classList.add('cm-with-icon');
 }
 });}
const cmIconObserver=new MutationObserver(()=>decorateIcons());
cmIconObserver.observe(document.getElementById('app'),{childList:true,subtree:true});
cmIconObserver.observe(document.getElementById('modal'),{childList:true,subtree:true});
decorateIcons();
